import subprocess, sqlite3, tempfile, os
repo = r'D:\repository\skills'
head = subprocess.run(['git','-C',repo,'show','HEAD:deploy-env/registry.sqlite'],capture_output=True).stdout
tmp = os.path.join(tempfile.gettempdir(),'_head_registry_check2.sqlite')
open(tmp,'wb').write(head)
cur = sqlite3.connect(r'D:\repository\skills\deploy-env\registry.sqlite')
old = sqlite3.connect(tmp)
for t in ('env_registry','env_accounts'):
    cc = cur.execute('select * from '+t).description
    cols = [d[0] for d in cc]
    ck = {r[0]: r for r in cur.execute('select * from '+t)}
    ok = {r[0]: r for r in old.execute('select * from '+t)}
    diffcols = set()
    for k in list(ck)[:30]:
        if k in ok:
            for i,c in enumerate(cols):
                if ck[k][i] != ok[k][i]:
                    diffcols.add(c)
    print(t, 'diff_columns=', sorted(diffcols))
cur.close(); old.close(); os.remove(tmp)
